/**
 * Unit tests for SimplexTableau#getSolution.
 * Since the method is protected, we use a spy or a subclass to test it.
 */
public class SimplexTableau_getSolution_TriageGen1Test {

    // Using a subclass to expose the protected method for testing
    private static class TestableSimplexTableau extends SimplexTableau {
        public TestableSimplexTableau(RealMatrix tableau, boolean maximize) {
            super(tableau, maximize);
        }

        @Override
        public RealPointValuePair getSolution() {
            return super.getSolution();
        }
    }

    // Mocking the objective function f
    private static class MockObjectiveFunction implements org.apache.commons.math3.optim.nonlinear.scalar.ObjectiveFunction {
        private final double value;
        public MockObjectiveFunction(double value) { this.value = value; }
        @Override
        public double getValue(RealVector point) { return value; }
    }

    @Test
    public void testGetSolution_RestrictToNonNegative_True() throws Exception {
        // Setup a scenario where restrictToNonNegative is true
        // columnLabels: ["x0", "x1", "NEGATIVE_VAR_COLUMN_LABEL", "RHS"]
        // basicRows: x0 -> row 1, x1 -> row 2

        // We need to mock the internal state via a spy because the method relies heavily on 
        // internal state like columnLabels, getBasicRow, getEntry, etc.

        // Since we cannot easily inject columnLabels directly into the private field via standard API, 
        // we assume a setup where the tableau is constructed. 
        // For the purpose of this unit test, we rely on the fact that we can mock the protected methods 
        // using a Spy on the TestableSimplexTableau.

        RealMatrix matrix = org.apache.commons.math3.linear.MatrixUtils.createRealMatrix(3, 4);
        TestableSimplexTableau tableau = spy(new TestableSimplexTableau(matrix, true));

        // Mocking internal behavior via spy
        when(tableau.getOriginalNumDecisionVariables()).thenReturn(2);
        when(tableau.getRhsOffset()).thenReturn(3);
        // Mocking columnLabels indirectly by forcing the behavior of indexOf
        // Note: In a real scenario, we'd use reflection to set columnLabels if necessary, 
        // but here we simulate the logic flow.

        // To test the branch: int negativeVarColumn = columnLabels.indexOf(NEGATIVE_VAR_COLUMN_LABEL);
        // We need to mock the behavior of the tableau's state.
        // However, SimplexTableau's columnLabels is private. 
        // In professional testing of legacy/protected code, we use Reflection.

        java.lang.reflect.Field labelsField = SimplexTableau.class.getDeclaredField("columnLabels");
        labelsField.setAccessible(true);
        java.util.List<String> labels = java.util.Arrays.asList("x0", "x1", "NEGATIVE_VAR_COLUMN_LABEL", "RHS");
        labelsField.set(tableau, labels);

        // Mocking restrictToNonNegative via reflection or by observing behavior
        // The code uses 'restrictToNonNegative' which is a field in SimplexTableau
        java.lang.reflect.Field restrictField = SimplexTableau.class.getDeclaredField("restrictToNonNegative");
        restrictField.setAccessible(true);
        restrictField.set(tableau, true);

        // Mocking getBasicRow and getEntry
        when(tableau.getBasicRow(0)).thenReturn(1); // x0 is in row 1
        when(tableau.getBasicRow(1)).thenReturn(2); // x1 is in row 2
        when(tableau.getEntry(1, 3)).thenReturn(10.0); // x0 value
        when(tableau.getEntry(2, 3)).thenReturn(20.0); // x1 value

        // Mocking the objective function 'f'
        java.lang.reflect.Field fField = SimplexTableau.class.getDeclaredField("f");
        fField.setAccessible(true);
        fField.set(tableau, new MockObjectiveFunction(30.0));

        RealPointValuePair result = tableau.getSolution();

        assertEquals(10.0, result.getPoint().getEntry(0), 1e-9);
        assertEquals(20.0, result.getPoint().getEntry(1), 1e-9);
        assertEquals(30.0, result.getValue(), 1e-9);
    }

    @Test
    public void testGetSolution_RestrictToNonNegative_False_WithNegativeVar() throws Exception {
        RealMatrix matrix = org.apache.commons.math3.linear.MatrixUtils.createRealMatrix(4, 4);
        TestableSimplexTableau tableau = spy(new TestableSimplexTableau(matrix, true));

        java.lang.reflect.Field labelsField = SimplexTableau.class.getDeclaredField("columnLabels");
        labelsField.setAccessible(true);
        java.util.List<String> labels = java.util.Arrays.asList("x0", "x1", "NEGATIVE_VAR_COLUMN_LABEL", "RHS");
        labelsField.set(tableau, labels);

        java.lang.reflect.Field restrictField = SimplexTableau.class.getDeclaredField("restrictToNonNegative");
        restrictField.setAccessible(true);
        restrictField.set(tableau, false);

        when(tableau.getOriginalNumDecisionVariables()).thenReturn(2);
        when(tableau.getRhsOffset()).thenReturn(3);

        // negativeVarColumn = 2. getBasicRow(2) = 0. 
        // mostNegative = getEntry(0, 3) = -5.0
        when(tableau.getBasicRow(2)).thenReturn(0);
        when(tableau.getEntry(0, 3)).thenReturn(-5.0);

        // x0: basicRow = 1, getEntry(1,3) = 15.0. coeff = 15.0 - (-5.0) = 20.0
        // x1: basicRow = 1 (duplicate), coeff = 0 - (-5.0) = 5.0
        when(tableau.getBasicRow(0)).thenReturn(1);
        when(tableau.getBasicRow(1)).thenReturn(1);
        when(tableau.getEntry(1, 3)).thenReturn(15.0);

        java.lang.reflect.Field fField = SimplexTableau.class.getDeclaredField("f");
        fField.setAccessible(true);
        fField.set(tableau, new MockObjectiveFunction(25.0));

        RealPointValuePair result = tableau.getSolution();

        assertEquals(20.0, result.getPoint().getEntry(0), 1e-9);
        assertEquals(5.0, result.getPoint().getEntry(1), 1e-9);
        assertEquals(25.0, result.getValue(), 1e-9);
    }

    @Test
    public void testGetSolution_MissingColumnLabel() throws Exception {
        RealMatrix matrix = org.apache.commons.math3.linear.MatrixUtils.createRealMatrix(2, 2);
        TestableSimplexTableau tableau = spy(new TestableSimplexTableau(matrix, true));

        java.lang.reflect.Field labelsField = SimplexTableau.class.getDeclaredField("columnLabels");
        labelsField.setAccessible(true);
        // "x1" is missing from labels
        java.util.List<String> labels = java.util.Arrays.asList("x0", "NEGATIVE_VAR_COLUMN_LABEL", "RHS");
        labelsField.set(tableau, labels);

        java.lang.reflect.Field restrictField = SimplexTableau.class.getDeclaredField("restrictToNonNegative");
        restrictField.setAccessible(true);
        restrictField.set(tableau, true);

        when(tableau.getOriginalNumDecisionVariables()).thenReturn(2);
        when(tableau.getRhsOffset()).thenReturn(2);

        // negativeVarColumn = 1. getBasicRow(1) = null. mostNegative = 0.
        when(tableau.getBasicRow(1)).thenReturn(null);

        // x0: colIndex = 0. basicRow = 1. getEntry(1,2) = 10.0
        when(tableau.getBasicRow(0)).thenReturn(1);
        when(tableau.getEntry(1, 2)).thenReturn(10.0);

        // x1: colIndex = -1. coefficients[1] = 0.

        java.lang.reflect.Field fField = SimplexTableau.class.getDeclaredField("f");
        fField.setAccessible(true);
        fField.set(tableau, new MockObjectiveFunction(10.0));

        RealPointValuePair result = tableau.getSolution();

        assertEquals(10.0, result.getPoint().getEntry(0), 1e-9);
        assertEquals(0.0, result.getPoint().getEntry(1), 1e-9);
        assertEquals(10.0, result.getValue(), 1e-9);
    }

    @Test
    public void testGetSolution_NoNegativeVarColumn() throws Exception {
        RealMatrix matrix = org.apache.commons.math3.linear.MatrixUtils.createRealMatrix(2, 2);
        TestableSimplexTableau tableau = spy(new TestableSimplexTableau(matrix, true));

        java.lang.reflect.Field labelsField = SimplexTableau.class.getDeclaredField("columnLabels");
        labelsField.setAccessible(true);
        java.util.List<String> labels = java.util.Arrays.asList("x0", "RHS");
        labelsField.set(tableau, labels);

        java.lang.reflect.Field restrictField = SimplexTableau.class.getDeclaredField("restrictToNonNegative");
        restrictField.setAccessible(true);
        restrictField.set(tableau, true);

        when(tableau.getOriginalNumDecisionVariables()).thenReturn(1);
        when(tableau.getRhsOffset()).thenReturn(1);

        // negativeVarColumn = -1. mostNegative = 0.
        when(tableau.getBasicRow(0)).thenReturn(0);
        when(tableau.getEntry(0, 1)).thenReturn(5.0);

        java.lang.reflect.Field fField = SimplexTableau.class.getDeclaredField("f");
        fField.setAccessible(true);
        fField.set(tableau, new MockObjectiveFunction(5.0));

        RealPointValuePair result = tableau.getSolution();

        assertEquals(5.0, result.getPoint().getEntry(0), 1e-9);
        assertEquals(5.0, result.getValue(), 1e-9);
    }
}
